(function(){
 const incoming=[{"id":"social-course-firm-1-20261108","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","topicOrder":9,"part":1,"cardTitle":"Базовый тест","label":"Базовый тест","title":"Политика защиты конкуренции. Предприятие (фирма) в экономике · Базовый тест","period":"Обществознание","description":"15 заданий: конкуренция, факторы производства, издержки и финансирование бизнеса.","sourceNote":"StudyCats. Неоднозначные условия уточнены.","questions":[{"id":"sc-firm-1-q1","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 1","ex":"1 — верно: взнос собственника поступает извне по отношению к самой фирме; его следует отличать от средств, заработанных фирмой. 2 — верно: самофинансирование ограничено внутренними ресурсами. 3 — неверно: частный бизнес может получать бюджетные субсидии и гранты. 4 — верно: кредиты и займы привлекаются извне. 5 — верно: использование средств самой фирмы не требует привлечения новых кредиторов или совладельцев.","type":"multi","q":"Выберите верные суждения о финансировании бизнеса и запишите цифры под которыми они указаны.","options":[{"id":"1","label":"Средства, которые собственник вносит в капитал создаваемой фирмы из личных сбережений, поступают в фирму извне."},{"id":"2","label":"Уровень самофинансирования предприятия зависит от его внутренних возможностей."},{"id":"3","label":"Финансирование частного бизнеса не может носить государственный характер."},{"id":"4","label":"К внешним источникам финансирования относят заемный капитал."},{"id":"5","label":"Финансирование за счёт собственных средств упрощает процесс принятия управленческих решений по развитию предприятия."}],"answer":["1","2","4","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q2","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 2","ex":"Внешние (явные) издержки - это ресурсы, необходимые для производства экономических благ, но не являющиеся собственностью фирм - неверно, внешние издержки - это не сами ресурсы, а денежные затраты на их приобретение.\n\nПоложительный эффект масштаба производства заключается в сокращении издержек на единицу продукции - верно, это явление, при котором средние затраты на производство единицы товара снижаются по мере увеличения объёма производства.\n\nВнешние (явные) издержки – это затраты на приобретение материалов, не принадлежащих фирме - верно, внешние (явные) издержки — это реальные денежные платежи фирмы за ресурсы, которые ей не принадлежат. Сюда действительно относятся затраты на сырье, материалы, комплектующие, энергию, аренду, оплату труда наемных работников и т.д.\n\nСебестоимость продукции включает в себя только постоянные издержки. - неверно, себестоимость продукции - это совокупность всех затрат на производство и реализацию. Она включает как постоянные (аренда, оклады администрации), так и переменные издержки (сырье, сдельная зарплата, энергия для оборудования).\n\nВеличина переменных издержек зависит от объёма производства. - верно, это ключевой признак переменных издержек. Чем больше объем выпускаемой продукции, тем выше затраты на сырье, материалы, транспорт, оплату труда сдельщиков и т.п.","type":"multi","q":"Выберите верные суждения об издержках производства и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Внешние (явные) издержки - это ресурсы, необходимые для производства экономических благ, но не являющиеся собственностью фирм"},{"id":"2","label":"Положительный эффект масштаба производства заключается в сокращении издержек на единицу продукции"},{"id":"3","label":"Внешние (явные) издержки включают денежные затраты на приобретение материалов у сторонних поставщиков."},{"id":"4","label":"Себестоимость продукции включает в себя только постоянные издержки."},{"id":"5","label":"Величина переменных издержек зависит от объёма производства."}],"answer":["2","3","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q3","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 3","ex":"Постоянные расходы 1, 3, 4, 6 заданы как фиксированные в краткосрочном периоде. Расходы на топливо и сдельная оплата курьеров (2, 5) зависят от количества доставок. Амортизация отражает постепенный перенос стоимости основных средств, а не разовый ремонт сломанного оборудования.","type":"multi","q":"Фирма \"Скороход\" оказывает услуги курьерской доставки. Найдите в приведённом списке примеры постоянных издержек фирмы в краткосрочном периоде и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"фиксированная плата за лицензию на логистическое программное обеспечение"},{"id":"2","label":"заправка курьерских автомобилей"},{"id":"3","label":"фиксированная плата за размещение рекламы в Интернете на месяц"},{"id":"4","label":"амортизационные отчисления, начисляемые линейным методом"},{"id":"5","label":"выплаты курьерам по числу выполненных доставок"},{"id":"6","label":"фиксированная плата за обслуживание офиса, не зависящая от количества доставок"}],"answer":["1","3","4","6"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q4","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 4","ex":"Бухгалтерская прибыль – это разница между доходами и всеми издержками (скрытыми и явными) - неверно, бухгалтерская прибыль - это разница между общей выручкой фирмы и бухгалтерскими издержками.\n\nПрибыль фирмы рассматривается как внешний источник финансирования бизнеса. - неверно, это внутренний источник финансирования, так как она образуется из доходов самой фирмы и остается в распоряжении предприятия.\n\nОсновной недостаток самофинансирования бизнеса связан с ограниченностью имеющихся у его владельцев средств. - верно, самофинансирование ограничено собственными средствами владельцев, что может препятствовать росту бизнеса\n\nМногие предприятия заинтересованы в долгосрочном привлечении заёмных средств. - верно, долгосрочные заемные средства позволяют планировать развитие и инвестиции на длительный срок, поэтому многие предприятия действительно заинтересованы в их привлечении.\n\nНаращивание объёмов внешнего финансирования бизнеса повышает степень контроля собственника за предприятием. - неверно, внешнее финансирование, особенно заемное или через выпуск акций, может привести к уменьшению контроля собственника.","type":"multi","q":"Выберите верные суждения о финансировании бизнеса и запишите цифры под которыми они указаны.","options":[{"id":"1","label":"Бухгалтерская прибыль – это разница между доходами и всеми издержками (скрытыми и явными)"},{"id":"2","label":"Прибыль фирмы рассматривается как внешний источник финансирования бизнеса."},{"id":"3","label":"Основной недостаток самофинансирования бизнеса связан с ограниченностью имеющихся у его владельцев средств."},{"id":"4","label":"Многие предприятия заинтересованы в долгосрочном привлечении заёмных средств."},{"id":"5","label":"Наращивание объёмов внешнего финансирования бизнеса повышает степень контроля собственника за предприятием."}],"answer":["3","4"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q5","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 5","ex":"Исключения — 2 и 5: фиксированные платежи за обслуживание офиса и линейная амортизация не зависят от объёма выпуска. Упаковка, сдельная оплата, производственное потребление воды и сырьё — переменные издержки.","type":"multi","q":"Ниже приведён перечень примеров издержек фирмы в краткосрочном периоде. Все они, за исключением двух, являются переменными издержками. Найдите два термина, «выпадающих» из общего ряда.","options":[{"id":"1","label":"расходы на упаковочный материал"},{"id":"2","label":"фиксированная плата за отопление и обслуживание офиса"},{"id":"3","label":"сдельная оплата труда наёмных работников"},{"id":"4","label":"плата за воду, потреблённую в производственном процессе"},{"id":"5","label":"амортизационные отчисления при линейном методе начисления"},{"id":"6","label":"приобретение сырья и расходных материалов"}],"answer":["2","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q6","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 6","ex":"Внутреннее финансирование бизнеса не сопряжено с дополнительными расходами, связанными с привлечением капитала. - верно, у внутренних средств нет платы за привлечение: не нужно платить проценты по кредиту, дивиденды или расходы на выпуск акций\n\nПод финансированием понимается процесс образования денежных средств или, в более широком плане, процесс образования капитала фирмы во всех его формах. - верно, это корректное определение финансирования как процесса формирования финансовых ресурсов (капитала) компании.\n\nВнешнее финансирование всегда обеспечивает финансовую независимость предприятия. - неверно, чаще всего внешнее финансирование, наоборот, снижает финансовую независимость. Кредиторы и инвесторы накладывают обязательства (проценты, сроки возврата, условия по управлению), что ограничивает свободу действий компании.\n\nК внутренним источникам финансирования бизнеса относят заёмный капитал. - неверно, заёмный капитал (кредиты, займы) - это пример внешнего источника финансирования, так как привлекается извне от кредиторов.\n\nB условиях рыночной экономики производственно-хозяйственная деятельность фирм может осуществляться с привлечением заёмных средств. - верно, использование заёмного капитала (кредитов, облигаций) - это стандартная и широко распространенная практика для компаний в рыночной экономике, позволяющая финансировать развитие и текущие операции.","type":"multi","q":"Выберите верные суждения о финансировании бизнеса и его источниках и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Внутреннее финансирование бизнеса не сопряжено с дополнительными расходами, связанными с привлечением капитала."},{"id":"2","label":"Под финансированием понимается процесс образования денежных средств или, в более широком плане, процесс образования капитала фирмы во всех его формах."},{"id":"3","label":"Внешнее финансирование всегда обеспечивает финансовую независимость предприятия."},{"id":"4","label":"К внутренним источникам финансирования бизнеса относят заёмный капитал."},{"id":"5","label":"B условиях рыночной экономики производственно-хозяйственная деятельность фирм может осуществляться с привлечением заёмных средств."}],"answer":["1","2","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q7","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 7","ex":"А, Б — переменные: расход упаковки и указанных материалов растёт вместе с количеством заказов. В, Г, Д — постоянные: оклады администрации, фиксированные проценты по кредиту и лицензионные платежи в краткосрочном периоде не зависят от выпуска.","type":"match","q":"Установите соответствие между примерами и видами издержек фирмы в краткосрочном периоде: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.","options":["постоянные","переменные"],"rows":[{"id":"row1","label":"расходы на упаковочный материал","answer":"переменные"},{"id":"row2","label":"расходы на канцелярские материалы, потребление которых растёт пропорционально числу выполненных заказов","answer":"переменные"},{"id":"row3","label":"оклады администрации","answer":"постоянные"},{"id":"row4","label":"выплата процентов по кредитам (обслуживание кредита)","answer":"постоянные"},{"id":"row5","label":"фиксированная лицензионная плата за использование программного обеспечения","answer":"постоянные"}],"hint":"Сначала определите признак каждой категории, затем сопоставьте с ним каждый пример. Постоянные издержки не зависят от объёма выпуска; переменные изменяются вместе с ним."},{"id":"sc-firm-1-q8","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 8","ex":"средства амортизационного фонда - неверно, это внутренний источник финансирования. Амортизационные отчисления накапливаются и могут быть использованы для обновления основных фондов.\n\nповышение производительности труда - верно, это не источник финансирования, а способ повышения эффективности производства. Он не приносит непосредственно денежные средства.\n\nприбыль от реализации продукции предприятия - неверно, это внутренний источник финансирования (нераспределенная прибыль).\n\nпривлечение кредитов - неверно, это внешний источник финансирования (заемные средства).\n\nсовершенствование производственных технологий - верно, это не источник финансирования, а процесс улучшения производства. Он не предоставляет денежные средства.\n\nвыпуск и размещение акций предприятия - неверно, это внешний источник финансирования (привлеченные средства от продажи акций).","type":"multi","q":"Абрам Лазаревич составляет бизнес-план развития своего предприятия. Что из перечисленного ниже он не может использовать как источники финансирования бизнеса? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"средства амортизационного фонда"},{"id":"2","label":"повышение производительности труда"},{"id":"3","label":"прибыль от реализации продукции предприятия"},{"id":"4","label":"привлечение кредитов"},{"id":"5","label":"совершенствование производственных технологий"},{"id":"6","label":"выпуск и размещение акций предприятия"}],"answer":["2","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q9","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 9","ex":"Переменные издержки в краткосрочном периоде непосредственно зависят от объёма производимой продукции. - верно, это ключевая характеристика переменных издержек: их величина изменяется в зависимости от объёма производства.\n\nК постоянным издержкам в краткосрочном периоде относят процент банку за кредит, плату за охрану помещения. - верно, эти расходы действительно относятся к постоянным издержкам, так как они не зависят от объема производства в краткосрочном периоде и должны выплачиваться независимо от того, сколько продукции выпускает фирма.\n\nСебестоимостью продукции называют сумму постоянных издержек. - неверно, себестоимость включает все издержки производства: как постоянные, так и переменные. Это сумма полных затрат на производство и реализацию продукции.\n\nИздержки - это денежная оценка затрат всех ресурсов, задействованных в производстве. - верно, это корректное экономическое определение издержек.\n\nК постоянным издержкам в краткосрочном периоде относят страховые взносы на бизнес – верно. Страхование бизнеса (имущества, помещения, оборудования, ответственности) оплачивается фиксированной суммой по договору. Эта сумма не зависит от того, сколько продукции выпускает фирма, и платить её нужно даже при остановленном производстве.","type":"multi","q":"Выберите верные суждения об издержках в краткосрочном периоде и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Переменные издержки в краткосрочном периоде непосредственно зависят от объёма производимой продукции."},{"id":"2","label":"К постоянным издержкам в краткосрочном периоде относят процент банку за кредит, плату за охрану помещения."},{"id":"3","label":"Себестоимостью продукции называют сумму постоянных издержек."},{"id":"4","label":"Издержки - это денежная оценка затрат всех ресурсов, задействованных в производстве."},{"id":"5","label":"К постоянным издержкам в краткосрочном периоде относят фиксированные взносы по страхованию имущества фирмы."}],"answer":["1","2","4","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q10","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 10","ex":"Внутреннее финансирование предполагает использование собственных средств предприятия. - верно, внутреннее финансирование действительно осуществляется за счет собственных ресурсов предприятия - нераспределенной прибыли, амортизационных отчислений, резервных фондов.\n\nПривлечение кредитов рассматривается как внутренний источник финансирования бизнеса. - неверно, кредиты являются примером внешнего источника финансирования, поскольку привлекаются от сторонних организаций (банков, кредитных учреждений) и не формируются за счет внутренней деятельности предприятия.\n\nПри выборе источников финансирования осуществляется прогнозирование возможных изменений в составе активов и капитала предприятия. - верно, выбор источников финансирования действительно требует тщательного анализа и прогнозирования, поскольку разные источники по-разному влияют на структуру активов, пассивов, стоимость капитала и финансовую устойчивость предприятия.\n\nВнешние источники финансирования – это источники поступления денежных средств, которые образованы за счёт результатов предпринимательской деятельности предприятия. - неверно, это определение описывает внутренние источники финансирования (прибыль, амортизационные отчисления). Внешние источники формируются за пределами предприятия - кредиты, инвестиции, государственное финансирование.\n\nБанки аккумулируют сбережения домохозяйств и направляют часть из них на финансирование бизнеса. - верно, это основная функция банков как финансовых посредников: они привлекают средства населения (депозиты) и направляют их на кредитование предприятий, обеспечивая перераспределение финансовых ресурсов в экономике.","type":"multi","q":"Выберите верные суждения о финансировании бизнеса и запишите цифры под которыми они указаны.","options":[{"id":"1","label":"Внутреннее финансирование предполагает использование собственных средств предприятия."},{"id":"2","label":"Привлечение кредитов рассматривается как внутренний источник финансирования бизнеса."},{"id":"3","label":"При выборе источников финансирования осуществляется прогнозирование возможных изменений в составе активов и капитала предприятия."},{"id":"4","label":"Внешние источники финансирования – это источники поступления денежных средств, которые образованы за счёт результатов предпринимательской деятельности предприятия."},{"id":"5","label":"Банки аккумулируют сбережения домохозяйств и направляют часть из них на финансирование бизнеса."}],"answer":["1","3","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q11","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 11","ex":"А — земля; Б и Г — капитал (созданные человеком средства производства); В — труд; Д — предпринимательские способности.","type":"match","q":"Установите соответствие между характеристиками и факторами производства: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.","options":["земля","капитал","труд","предпринимательство (предпринимательские способности)"],"rows":[{"id":"row1","label":"все виды полезных ископаемых","answer":"земля"},{"id":"row2","label":"станки и производственные инструменты","answer":"капитал"},{"id":"row3","label":"деятельность людей по производству товаров и услуг путём использования профессиональных навыков и опыта","answer":"труд"},{"id":"row4","label":"здания и сооружения, оборудование, инфраструктура и др.","answer":"капитал"},{"id":"row5","label":"инициативная новаторская деятельность, благодаря которой происходит соединение всех факторов производства","answer":"предпринимательство (предпринимательские способности)"}],"hint":"Сначала определите признак каждой категории, затем сопоставьте с ним каждый пример. Постоянные издержки не зависят от объёма выпуска; переменные изменяются вместе с ним."},{"id":"sc-firm-1-q12","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 12","ex":"Финансирование - способ обеспечения предприятия денежными средствами - верно, это верное определение финансирования как процесса обеспечения компании финансовыми ресурсами.\n\nК внутренним источникам финансирования бизнеса относится сдача в аренду неиспользуемых активов фирмы. - верно, доход от аренды собственного имущества компании относится к внутренним источникам, поскольку образуется за счет использования активов, уже принадлежащих предприятию.\n\nК внутренним источникам финансирования относят заёмный и привлечённый капитал - неверно, заемный капитал (кредиты, займы) и привлеченный капитал (средства от выпуска акций) являются внешними источниками финансирования, поскольку привлекаются от сторонних лиц и организаций.\n\nК внешним источникам финансирования бизнеса относят амортизационные отчисления. - неверно, амортизационные отчисления являются примером внутреннего источника финансирования, так как образуются в процессе хозяйственной деятельности предприятия за счет собственных средств.\n\nВнешнее финансирование бизнеса может осуществляться из средств государственного бюджета. - верно, государство действительно может выступать внешним источником финансирования через субсидии, гранты, государственные заказы, налоговые льготы и другие формы поддержки бизнеса.","type":"multi","q":"Выберите верные суждения о финансировании бизнеса и запишите цифры под которыми они указаны.","options":[{"id":"1","label":"Финансирование - способ обеспечения предприятия денежными средствами"},{"id":"2","label":"К внутренним источникам финансирования бизнеса относится сдача в аренду неиспользуемых активов фирмы."},{"id":"3","label":"К внутренним источникам финансирования относят заёмный и привлечённый капитал"},{"id":"4","label":"К внешним источникам финансирования бизнеса относят амортизационные отчисления."},{"id":"5","label":"Внешнее финансирование бизнеса может осуществляться из средств государственного бюджета."}],"answer":["1","2","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q13","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 13","ex":"А — земля; Б — труд; В и Г — капитал (оборудование и орудия труда); Д — предпринимательские способности.","type":"match","q":"Установите соответствие между характеристиками и факторами производства: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.","options":["земля","капитал","труд","предпринимательство (предпринимательские способности)"],"rows":[{"id":"row1","label":"все виды природных ресурсов, имеющихся на планете и пригодных для производства жизненных благ","answer":"земля"},{"id":"row2","label":"непосредственное использование физических и умственных способностей в процессе создания экономических благ","answer":"труд"},{"id":"row3","label":"производственное оборудование","answer":"капитал"},{"id":"row4","label":"орудия труда","answer":"капитал"},{"id":"row5","label":"умение организовать производство","answer":"предпринимательство (предпринимательские способности)"}],"hint":"Сначала определите признак каждой категории, затем сопоставьте с ним каждый пример. Постоянные издержки не зависят от объёма выпуска; переменные изменяются вместе с ним."},{"id":"sc-firm-1-q14","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 14","ex":"Факторный доход с капитала называется рентой. - неверно, рента - это факторный доход с земли, доход с капитала называется процентом.\n\nДоход собственника капитала - процент. - верно, процент является доходом от капитала.\n\nКачественные характеристики труда как фактора производства отражают уровень квалификации работников - верно, качество труда действительно определяется квалификацией, образованием, профессиональным опытом и навыками работников, что напрямую влияет на производительность и эффективность труда.\n\nК трудовым ресурсам относят всё население страны. - неверно, к трудовым ресурсам относится только трудоспособное население\n\nПод предпринимательскими способностями как фактором производства понимают готовность человека к самостоятельной инициативной экономической деятельности, осуществляемой на свой риск в целях получения прибыли - верно, это корректное определение предпринимательских способностей как особого фактора производства, включающего инновации, риск и организацию других факторов производства.","type":"multi","q":"Выберите верные суждения о факторах производства и факторных доходах и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Факторный доход с капитала называется рентой."},{"id":"2","label":"Доход собственника капитала - процент."},{"id":"3","label":"Качественные характеристики труда как фактора производства отражают уровень квалификации работников."},{"id":"4","label":"К трудовым ресурсам относят всё население страны."},{"id":"5","label":"Под предпринимательскими способностями как фактором производства понимают готовность человека к самостоятельной инициативной экономической деятельности, осуществляемой на свой риск в целях получения прибыли"}],"answer":["2","3","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-1-q15","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4093b855-9e6b-4257-b6eb-c27a4e113c71","sourceLabel":"StudyCats · Предприятие в экономике · База · вопрос 15","ex":"А и Д — краткосрочные преимущества, которые конкуренты могут воспроизвести. Б, В и Г — долгосрочные: квалифицированная команда, устойчивый исключительный доступ к редким ресурсам и узнаваемый бренд.","type":"match","q":"Установите соответствие между примерами и видами конкурентных преимуществ фирмы: к каждому элементу первого столбца подберите соответствующий элемент из второго столбца.","options":["краткосрочные","долгосрочные"],"rows":[{"id":"row1","label":"наличие дешёвых трудовых ресурсов","answer":"краткосрочные"},{"id":"row2","label":"привлечение наиболее квалифицированных специалистов","answer":"долгосрочные"},{"id":"row3","label":"устойчивый исключительный доступ к редким ресурсам, недоступным конкурентам","answer":"долгосрочные"},{"id":"row4","label":"известный бренд","answer":"долгосрочные"},{"id":"row5","label":"льготные кредиты","answer":"краткосрочные"}],"hint":"Сначала определите признак каждой категории, затем сопоставьте с ним каждый пример. Постоянные издержки не зависят от объёма выпуска; переменные изменяются вместе с ним."}]},{"id":"social-course-firm-2-20261108","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","topicOrder":9,"part":2,"cardTitle":"Повышенная сложность","label":"Повышенная сложность","title":"Политика защиты конкуренции. Предприятие (фирма) в экономике · Повышенная сложность","period":"Обществознание","description":"10 заданий: конкуренция, факторы производства, издержки и финансирование бизнеса.","sourceNote":"StudyCats. Неоднозначные условия уточнены.","questions":[{"id":"sc-firm-2-q1","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 1","ex":"Политика защиты конкуренции (антимонопольная политика) — это деятельность государства, которая направлена на поддержку конкурентной среды, предупреждение и пресечение монополистической деятельности и недобросовестной конкуренции.\n\nАнтимонопольная политика государства направлена на запрет любых крупных предприятий, занимающих значительную долю рынка. — неверно, крупный размер фирмы и даже доминирующее положение на рынке сами по себе не запрещены. Запрещено злоупотребление доминирующим положением: установление монопольно высоких цен, навязывание невыгодных условий договора, создание барьеров для входа на рынок новых фирм.\n\nОдной из задач политики защиты конкуренции является предупреждение и пресечение недобросовестной конкуренции. — верно, государство запрещает недобросовестные способы борьбы с конкурентами: распространение ложных сведений о них, введение потребителей в заблуждение, незаконное использование чужого товарного знака.\n\nВ Российской Федерации контроль за соблюдением антимонопольного законодательства осуществляет Федеральная антимонопольная служба. — верно, ФАС России — федеральный антимонопольный орган. Он контролирует соблюдение закона «О защите конкуренции», рассматривает жалобы и может назначать штрафы за нарушения.\n\nДеятельность естественных монополий в Российской Федерации запрещена законом, поскольку они ограничивают конкуренцию. — неверно, естественные монополии (железнодорожные перевозки, транспортировка газа по трубопроводам, передача электроэнергии) не запрещены. Создавать в этих отраслях конкуренцию экономически невыгодно, поэтому государство их регулирует: устанавливает тарифы и контролирует деятельность.\n\nСоглашение конкурирующих фирм о поддержании единых цен является одной из форм ограничения конкуренции. — верно, это картельный сговор. Фирмы перестают конкурировать между собой и навязывают потребителям завышенные цены. Картельные соглашения запрещены законом.","type":"multi","q":"Выберите верные суждения о политике защиты конкуренции и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Антимонопольная политика государства направлена на запрет любых крупных предприятий, занимающих значительную долю рынка."},{"id":"2","label":"Одной из задач политики защиты конкуренции является предупреждение и пресечение недобросовестной конкуренции."},{"id":"3","label":"В Российской Федерации контроль за соблюдением антимонопольного законодательства осуществляет Федеральная антимонопольная служба."},{"id":"4","label":"Деятельность естественных монополий в Российской Федерации запрещена законом, поскольку они ограничивают конкуренцию."},{"id":"5","label":"Соглашение конкурирующих фирм о поддержании единых цен является одной из форм ограничения конкуренции."}],"answer":["2","3","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-2-q2","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 2","ex":"Внутренние источники финансирования - это те, которые возникают внутри самой фирмы из ее собственной деятельности.\nВнешние источники финансирования - это те, которые привлекаются извне.\n\nА) амортизационные отчисления - 1) внутренние, так как это средства, накопленные за счет износа оборудования, которые используются для обновления основных фондов.\n\nБ) доходы от собственности фирмы - 1) внутренние, например, доходы от сдачи имущества в аренду\n\nВ) выпуск и продажа ценных бумаг (средства от эмиссии акций) - 2) внешние, это привлечение средств от инвесторов.\n\nГ) государственный заказ - 2) внешние, это средства от государства.\n\nД) получение банковского кредита -2) внешние, это заемные средства извне.","type":"match","q":"Установите соответствие между примерами и видами источников финансирования бизнеса: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.","options":["внутренние","внешние"],"rows":[{"id":"row1","label":"амортизационные отчисления","answer":"внутренние"},{"id":"row2","label":"доходы от собственности фирмы","answer":"внутренние"},{"id":"row3","label":"выпуск и продажа ценных бумаг (средства от эмиссии акций)","answer":"внешние"},{"id":"row4","label":"государственный заказ","answer":"внешние"},{"id":"row5","label":"получение банковского кредита","answer":"внешние"}],"hint":"Сначала определите признак каждой категории, затем сопоставьте с ним каждый пример. Постоянные издержки не зависят от объёма выпуска; переменные изменяются вместе с ним."},{"id":"sc-firm-2-q3","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 3","ex":"Факторы производства – ресурсы, используемые людьми для производства необходимых экономических благ. Все факторы производства находятся в ограниченном количестве.\n\nвсе виды природных ресурсов, имеющихся на планете и пригодных для производства - верно, это прямое определение фактора земля.\n\nфакторный доход – рента - верно, для земли доходом является рента.\n\nфакторный доход – заработная плата - неверно, ЗП является доходом от такого фактора производства, как труд.\n\nограниченность ресурса проявляется в физическом и моральном износе зданий - неверно, это фактор капитал, а не земля.\n\nограниченность ресурса обусловлена разведанным объёмом полезных ископаемых, водных и других ресурсов - верно, это относится к ограниченности земли.\n\nограниченность ресурса обусловлена численностью трудоспособного населения - неверно, это относится к фактору труд, а не земля.","type":"multi","q":"Представьте, что Вы делаете презентацию к уроку обществознания по теме «Факторы производства». Один из слайдов называется «Земля как фактор производства». Что из перечисленного Вы включили бы в этот слайд? Запишите цифры, под которыми указаны эти признаки.","options":[{"id":"1","label":"все виды природных ресурсов, имеющихся на планете и пригодных для производства"},{"id":"2","label":"факторный доход – рента"},{"id":"3","label":"факторный доход – заработная плата"},{"id":"4","label":"ограниченность ресурса проявляется в физическом и моральном износе зданий"},{"id":"5","label":"ограниченность ресурса обусловлена разведанным объёмом полезных ископаемых, водных и других ресурсов"},{"id":"6","label":"ограниченность ресурса обусловлена численностью трудоспособного населения"}],"answer":["1","2","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-2-q4","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 4","ex":"Переменные - находятся на данный момент в прямой зависимости от объема производства и реализации продукции.\nПостоянные - не зависят на данный момент от объема выпускаемой продукции.\n\nА) амортизационные отчисления - 1) постоянные, так как они начисляются независимо от объема производства. \n\nБ) арендная плата за помещение - 1) постоянные, так как аренда платится фиксированно, независимо от объема выпуска. \n\nВ) взносы на застрахованное имущество фирмы - 1) постоянные, так как страховые взносы обычно фиксированы и не зависят от объема производства.\n\nГ) оплата потреблённой электроэнергии - 2) переменные, так как чем больше производится, тем больше электроэнергии потребляется. \n\nД) приобретение сырья и материалов - 2) переменные, так как они прямо зависят от объема производства.","type":"match","q":"Установите соответствие между примерами и видами издержек фирмы в краткосрочном периоде: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.","options":["постоянные","переменные"],"rows":[{"id":"row1","label":"амортизационные отчисления при линейном методе начисления","answer":"постоянные"},{"id":"row2","label":"арендная плата за помещение","answer":"постоянные"},{"id":"row3","label":"взносы на застрахованное имущество фирмы","answer":"постоянные"},{"id":"row4","label":"оплата электроэнергии, потреблённой производственным оборудованием","answer":"переменные"},{"id":"row5","label":"приобретение сырья и материалов","answer":"переменные"}],"hint":"Сначала определите признак каждой категории, затем сопоставьте с ним каждый пример. Постоянные издержки не зависят от объёма выпуска; переменные изменяются вместе с ним."},{"id":"sc-firm-2-q5","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 5","ex":"Постоянные издержки - это затраты, которые не зависят от объёма выпускаемой продукции и остаются неизменными в краткосрочном периоде.\n\nПеременные - находятся на данный момент в прямой зависимости от объема производства и реализации продукции.\n\nоплата потребления электроэнергии - неверно, зависит от объёма работы оборудования.\n\nвыплата окладов администрации - верно, оклады административного персонала являются фиксированными расходами.\n\nиздержки на приобретение расходных материалов - неверно, затраты на бумагу, краску и т.д. прямо связаны с количеством продукции.\n\nвыплата сдельной заработной платы работников - неверно, зависит от выполненного объёма работы.\n\nарендная плата за помещение - верно, арендные платежи обычно устанавливаются договором и не меняются с изменением объёма производства.\n\nвзносы по страхованию имущества фирмы - верно, страховые платежи фиксированы и не зависят от количества выпущенных книг.","type":"multi","q":"Издательство «Сепулька» занимается выпуском художественной литературы. Найдите в приведённом списке примеры постоянных издержек издательства в краткосрочном периоде и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"оплата электроэнергии, потреблённой производственным оборудованием"},{"id":"2","label":"выплата окладов администрации"},{"id":"3","label":"издержки на приобретение расходных материалов"},{"id":"4","label":"выплата сдельной заработной платы работников"},{"id":"5","label":"арендная плата за помещение"},{"id":"6","label":"взносы по страхованию имущества фирмы"}],"answer":["2","5","6"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-2-q6","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 6","ex":"К капиталу как фактору производства относятся созданные человеком средства производства: производственная линия (1), станки (3), компьютеры (4) и расходные материалы (6). Новые идеи (2) — информация, земельный участок (5) — земля. Банковский кредит является источником финансирования, поэтому в варианте 3 указан приобретённый производственный ресурс.","type":"multi","q":"Фирма «Мойдодыр» приняла решение об открытии нового направления по производству моющих средств. Какие из перечисленных факторов производства относятся к капиталу как к фактору производства? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"автоматизированная производственная линия"},{"id":"2","label":"ноу-хау, новейшие идеи инженеров компании"},{"id":"3","label":"станки, приобретённые для производства моющих средств"},{"id":"4","label":"компьютерное оборудование"},{"id":"5","label":"земля, арендованная под строительство новых зданий"},{"id":"6","label":"канцелярские товары"}],"answer":["1","3","4","6"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-2-q7","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 7","ex":"1 и 4 — верно: предприниматель организует использование ресурсов; факторы производства участвуют в создании благ. 2 — неверно: природные ресурсы относятся к земле, а капитал включает созданные человеком средства производства. 3 — неверно: доход земли — рента. 5 — неверно: прибыль зависит также от издержек, конкуренции и других условий.","type":"multi","q":"Выберите верные суждения о факторах производства и факторных доходах и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Предпринимательство – это инициативная рисковая деятельность, благодаря которой происходит соединение всех факторов производства."},{"id":"2","label":"Капитал как фактор производства включает только природные ресурсы."},{"id":"3","label":"Факторный доход земли - это процент."},{"id":"4","label":"Факторами производства называют ресурсы, которые непосредственно участвуют в производстве товаров и услуг."},{"id":"5","label":"Доход предпринимателя зависит только от спроса на его товар."}],"answer":["1","4"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-2-q8","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 8","ex":"Факторы производства – ресурсы, используемые людьми для производства необходимых экономических благ. Все факторы производства находятся в ограниченном количестве.\n\nЗемля - все виды природных ресурсов, имеющихся на планете и пригодных для производства экономических благ\n\nТруд - деятельность людей по производству товаров и услуг путем использования их физических и интеллектуальных\nспособностей, профессиональных навыков и опыта.\n\nКапитал - имущество, способное приносить доход.\n\nА) запасы минерального сырья - 1) земля \n\nБ) созданные человеком средства производства - 2) капитал \n\nВ) услуги, которые оказывают люди, способные скоординировать использование факторов производства и принять на себя риск - 4) предпринимательство (предпринимательские способности) \n\nГ) факторный доход – прибыль - 4) предпринимательство (предпринимательские способности) \n\nД) численность работников, занятых в производстве - 3) труд","type":"match","q":"Установите соответствие между характеристиками и факторами производства: к каждой позиции, данной в первом столбце, подберите соответствующую позицию из второго столбца.","options":["земля","капитал","труд","предпринимательство (предпринимательские способности)"],"rows":[{"id":"row1","label":"запасы минерального сырья","answer":"земля"},{"id":"row2","label":"созданные человеком средства производства","answer":"капитал"},{"id":"row3","label":"услуги, которые оказывают люди, способные скоординировать использование факторов производства и принять на себя риск","answer":"предпринимательство (предпринимательские способности)"},{"id":"row4","label":"факторный доход – прибыль","answer":"предпринимательство (предпринимательские способности)"},{"id":"row5","label":"численность работников, занятых в производстве","answer":"труд"}],"hint":"Сначала определите признак каждой категории, затем сопоставьте с ним каждый пример. Постоянные издержки не зависят от объёма выпуска; переменные изменяются вместе с ним."},{"id":"sc-firm-2-q9","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 9","ex":"К факторам производства традиционно относятся труд, земля, рынок, собственность. - неверно, традиционные факторы производства: труд, земля, капитал, предпринимательские способности. Рынок и собственность не являются факторами производства.\n\nТруд представляет собой совокупность физических и умственных способностей человека, используемых для создания экономических благ. - верно, это корректное определение труда как фактора производства.\n\nФакторными доходами называют ресурсы, используемые людьми для создания жизненных благ. - неверно, факторные доходы - это доходы от использования факторов производства (зарплата, рента, процент, прибыль), а не сами ресурсы.\n\nСобственник трудового ресурса получает доход, называемый прибылью. - неверно, владелец труда получает заработную плату. Прибыль - доход предпринимателя.\n\nВсе экономические ресурсы ограничены. - верно, ограниченность ресурсов относительно неограниченных потребностей - фундаментальная проблема экономики.","type":"multi","q":"Выберите верные суждения о факторах производства и факторных доходах и запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"К факторам производства традиционно относятся труд, земля, рынок, собственность."},{"id":"2","label":"Труд представляет собой совокупность физических и умственных способностей человека, используемых для создания экономических благ."},{"id":"3","label":"Факторными доходами называют ресурсы, используемые людьми для создания жизненных благ."},{"id":"4","label":"Собственник трудового ресурса получает доход, называемый прибылью."},{"id":"5","label":"Все экономические ресурсы ограничены."}],"answer":["2","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."},{"id":"sc-firm-2-q10","subject":"social","section":"course","topic":"Политика защиты конкуренции. Предприятие (фирма) в экономике","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/32dcfff2-1135-4f4f-99ed-bcab212c553c/test/4dd80263-3da9-4e1d-915b-a351ce1267ee","sourceLabel":"StudyCats · Предприятие в экономике · Про · вопрос 10","ex":"Переменные - находятся на данный момент в прямой зависимости от объема производства и реализации продукции.\n\nПостоянные - не зависят на данный момент от объёма выпускаемой продукции и остаются неизменными в краткосрочном периоде.\n\nоплата электроэнергии - верно, расход энергии изменяется в зависимости от загрузки производства.\n\nвыплата процентов по банковскому кредиту - неверно, это постоянные издержки, поскольку это фиксированный платеж.\n\nзатраты на приобретение древесины и металла - верно, это переменные издержки, так как их объем напрямую зависит от количества производимой продукции.\n\nфинансирование охранного предприятия и службы уборки - неверно, постоянные расходы, не зависящие от объема производства.\n\nсдельная заработная плата рабочих - верно, переменные издержки, поскольку рассчитывается исходя из объема выполненной работы.\n\nарендная плата за помещение магазина, в котором представлены образцы продукции - неверно, фиксированная сумма, не связанная с объемом выпуска.","type":"multi","q":"На предприятии «Окна и двери» проведена оптимизация издержек производства. Какие переменные издержки могли быть сокращены в процессе оптимизации? Запишите цифры, под которыми указаны соответствующие позиции.","options":[{"id":"1","label":"оплата электроэнергии, потреблённой производственным оборудованием"},{"id":"2","label":"выплата процентов по банковскому кредиту"},{"id":"3","label":"затраты на приобретение древесины и металла"},{"id":"4","label":"финансирование охранного предприятия и службы уборки"},{"id":"5","label":"сдельная заработная плата рабочих"},{"id":"6","label":"арендная плата за помещение магазина, в котором представлены образцы продукции"}],"answer":["1","3","5"],"hint":"Оцените каждое суждение отдельно. Различайте внутренние и внешние источники финансирования, постоянные и переменные издержки, а также факторы производства и их доходы."}]}];
 for(const test of incoming){if(!window.EGE_TESTS.some(t=>t.id===test.id))window.EGE_TESTS.push(test);window.EGE_VIDEO_LESSONS.byTest[test.id]=[{"url":"https://rutube.ru/play/embed/a864af463ef686e621e7a0c270f64a74/?p=gQi1MLtmVyEUgwUoYuxCGg","title":"Политика защиты конкуренции"},{"url":"https://rutube.ru/play/embed/1a70b0a9a0fc8ede349204d9fdfa3d75/?p=A245dRxBqHKqani1hI_W0Q","title":"Предпринимательская деятельность"},{"url":"https://rutube.ru/play/embed/6a0e510ea5aa92906029df7e7aca369b/?p=1KW2uxDS4PVzpg-nCzu_tw","title":"Малый бизнес"}];}
})();
